  if(shots.length){const sharp=shots.reduce((a,b)=>b.correct/b.attempts>a.correct/a.attempts?b:a);lines.push('🎯 Sharpshooter: '+sharp.name+' · '+Math.round(100*sharp.correct/sharp.attempts)+'% right');}
