  const m=/^([A-Z][A-Z ]{1,24}[A-Z])\s+[—-]\s+(.*)$/s.exec(String(text||''));if(!m)return String(text||'');
  const word=m[1].toLowerCase();
  if(word===String(label).toLowerCase())return m[2].charAt(0).toUpperCase()+m[2].slice(1);
